class Eval implements Visitor {                            // base operation, extensible
    protected Eval newEval(Env env) { return new Eval(env); }   // recursion is virtualized
    public void visit(Term t) { throw new UnsupportedOperationException("unhandled " + t); }
    public void visit(Apply a) { a.fn().accept(newEval(env)); }
}

final class XEval extends Eval implements XVisitor {          // the extension
    @Override protected Eval newEval(Env env) { return new XEval(env); }
    @Override public void visit(Term t) { if (t instanceof XTerm x) x.accept(this); else super.visit(t); }
    @Override public void visit(Plus p) { /* new element kind */ }
}
